import{_ as t,o,c as a,a3 as r}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"Storage — Developer Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Storage — Developer Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/developer-guide/storage"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Storage — Developer Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/developer-guide/storage"}]]},"headers":[],"relativePath":"developer-guide/storage.md","filePath":"developer-guide/storage.md","lastUpdated":1786668537000}'),c={name:"developer-guide/storage.md"};function i(d,e,s,l,n,p){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="storage-—-developer-guide" tabindex="-1">Storage — Developer Guide <a class="header-anchor" href="#storage-—-developer-guide" aria-label="Permalink to &quot;Storage — Developer Guide&quot;">​</a></h1><p>Capacity is <strong>module-entitlement metadata</strong>, not a Plans/Features/limits subsystem. Allowance is derived from entitled catalog slugs in <code>config/storage.php</code>.</p><h2 id="components" tabindex="-1">Components <a class="header-anchor" href="#components" aria-label="Permalink to &quot;Components&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Piece</th><th>Role</th></tr></thead><tbody><tr><td><code>config/storage.php</code></td><td>Free bytes + pack slug → bytes map</td></tr><tr><td><code>App\\Services\\Storage\\WorkspaceStorageService</code></td><td>Allowance, used bytes, assertCanStore, pack exclusivity</td></tr><tr><td><code>FileUploadService</code></td><td>Disk store/delete/url (unchanged)</td></tr><tr><td><code>GET /api/tenant/v1/storage/usage</code></td><td>Settings usage summary (<code>module:storage</code> + <code>storage.view</code>)</td></tr></tbody></table><h2 id="allowance-resolution" tabindex="-1">Allowance resolution <a class="header-anchor" href="#allowance-resolution" aria-label="Permalink to &quot;Allowance resolution&quot;">​</a></h2><ol><li>If any active <code>storage-*</code> pack is entitled → that pack’s bytes</li><li>Else if <code>storage</code> entitled → <code>free_bytes</code> (1 GiB)</li><li>Else → <code>0</code> → <code>STORAGE_REQUIRED</code></li></ol><h2 id="enforcement-points" tabindex="-1">Enforcement points <a class="header-anchor" href="#enforcement-points" aria-label="Permalink to &quot;Enforcement points&quot;">​</a></h2><p>Call <code>WorkspaceStorageService::assertCanStore($tenant, $incomingBytes)</code> <strong>before</strong> storing:</p><ul><li><code>ChatMessageService::attachFile</code></li><li><code>FeedbackService::attachFile</code></li><li><code>ImportManager::upload</code></li></ul><p>Do <strong>not</strong> gate <code>UserAvatarService</code> or branding uploads in <code>TenantSettingService</code>.</p><h2 id="used-bytes" tabindex="-1">Used bytes <a class="header-anchor" href="#used-bytes" aria-label="Permalink to &quot;Used bytes&quot;">​</a></h2><p>Sum of:</p><ul><li><code>chat_message_attachments.size_bytes</code></li><li><code>feedback_attachments.size_bytes</code></li><li><code>lead_imports.file_size</code></li><li>Disk size of import <code>error_report_path</code> / <code>failed_records_path</code> when present</li></ul><h2 id="pack-exclusivity" tabindex="-1">Pack exclusivity <a class="header-anchor" href="#pack-exclusivity" aria-label="Permalink to &quot;Pack exclusivity&quot;">​</a></h2><p><code>ModuleSubscriptionService::install</code> calls <code>assertCanInstallPack</code> (lazy-resolved to avoid DI cycles). Rejects a second pack while another is <code>active</code> / <code>trial</code> / <code>pending</code> with <code>STORAGE_PACK_CONFLICT</code>.</p><p>Upgrade UX: cancel current pack → purchase new pack (existing Marketplace flows).</p><h2 id="catalog-registration" tabindex="-1">Catalog registration <a class="header-anchor" href="#catalog-registration" aria-label="Permalink to &quot;Catalog registration&quot;">​</a></h2><p>Migrate-only via <code>DefaultModuleRegistrar::ensureModule</code>:</p><ul><li><code>2026_08_13_220700_register_storage_modules</code></li><li><code>2026_08_13_220710_add_storage_pack_dependencies</code></li><li><code>2026_08_13_220720_add_storage_permissions</code></li><li><code>2026_08_13_220730_grandfather_storage_for_team_chat_workspaces</code></li></ul><p>Mirror rows + dependencies in <code>CatalogSeeder</code> for local/CI.</p><h2 id="disks" tabindex="-1">Disks <a class="header-anchor" href="#disks" aria-label="Permalink to &quot;Disks&quot;">​</a></h2><p>See <a href="/developer-guide/object-storage">object-storage.md</a>. Production: content on <code>FILESYSTEM_UPLOADS_DISK=s3</code> (Wasabi); branding/avatars on <code>public</code> VPS disk.</p>',22)])])}const h=t(c,[["render",i]]);export{u as __pageData,h as default};
